frontend\\src\\styles\\globals.css:
:root {
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  font-synthesis: none;
  color: var(--dark-text);
  background: var(--background);
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
button,
input,
select,
textarea {
  font: inherit;
}
button {
  cursor: pointer;
  color: inherit;
}
button:disabled {
  opacity: 0.5;
  cursor: wait;
}
a {
  color: inherit;
  text-decoration: none;
}
img {
  display: block;
  max-width: 100%;
}
svg {
  flex-shrink: 0;
}
p {
  font-size: var(--supporting-font-size);
  line-height: 1.75;
  color: var(--muted);
  margin: 0 0 20px;
}
h1,
h2,
h3 {
  font-weight: 750;
  letter-spacing: -0.045em;
  line-height: 1.12;
  margin: 0 0 18px;
  color: var(--navy);
  overflow-wrap: break-word;
}
h1 {
  font-size: clamp(33px, 5vw, 62px);
}
h2 {
  font-size: var(--section-heading-size);
}
h3 {
  font-size: 20px;
  letter-spacing: -0.025em;
}
small {
  font-size: var(--small-font-size);
  line-height: 1.6;
  color: var(--muted);
}
a,
button,
input,
select,
textarea {
  -webkit-tap-highlight-color: transparent;
}
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible {
  outline: 3px solid #0088ce;
  outline-offset: 4px;
}
button,
a {
  touch-action: manipulation;
}
.button {
  min-height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 13px 20px;
  border-radius: 999px;
  background: var(--accent-orange);
  color: white;
  border: 1px solid transparent;
  font-size: var(--small-font-size);
  font-weight: 650;
  line-height: 1.3;
  transition:
    background 0.2s,
    box-shadow 0.2s,
    transform 0.2s;
}
.button:hover {
  background: #e65c08;
  box-shadow: 0 6px 22px #f96a1326;
  transform: translateY(-2px);
}
.button.secondary {
  background: white;
  color: var(--navy);
  border-color: #cbdde9;
}
.button.secondary:hover {
  background: var(--light-blue);
}
.button.light {
  background: white;
  color: var(--navy);
}
.icon {
  display: grid;
  place-items: center;
  min-width: 44px;
  min-height: 44px;
  background: none;
  border: 0;
  padding: 10px;
}
.eyebrow {
  display: block;
  font-size: var(--small-font-size);
  letter-spacing: 1.8px;
  font-weight: 750;
  line-height: 1.6;
  color: var(--blue);
  margin-bottom: 13px;
  text-transform: uppercase;
}
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: var(--small-font-size);
  font-weight: 650;
  color: var(--blue);
}
.text-link:hover svg,
.learn-link:hover svg {
  transform: translateX(4px);
}
.text-link svg,
.learn-link svg {
  transition: transform 0.2s;
}
.top-strip {
  display: none;
}
header {
  height: 78px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  border-bottom: 1px solid #e8eef3;
  position: sticky;
  top: 0;
  z-index: 45;
  gap: 16px;
  transition: box-shadow 0.25s;
}
header.scrolled {
  box-shadow: 0 6px 20px #082b4c0b;
}
.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  white-space: nowrap;
  color: var(--navy);
  font-size: 19px;
  letter-spacing: -0.85px;
  font-weight: 800;
}
.brand-light {
  color: var(--blue);
  font-weight: 700;
}
.brand small {
  display: block;
  font-size: var(--small-font-size);
  letter-spacing: 2.3px;
  color: #677f91;
  margin-top: 3px;
}
.logo {
  position: relative;
  display: block;
  width: 35px;
  height: 38px;
  color: var(--blue);
  flex-shrink: 0;
}
.logo > svg:first-child {
  width: 35px;
  height: 35px;
  stroke-width: 2.5;
}
.logo > svg:last-child {
  position: absolute;
  bottom: 1px;
  left: 12px;
  color: var(--accent-orange);
  background: #fff;
  stroke-width: 2.7;
}
.desktop-nav,
.tablet-menu {
  display: none;
}
.header-actions {
  display: flex;
  align-items: center;
}
.header-actions > .location-button,
.header-actions > .call {
  display: none;
}
.account-icon {
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  background: var(--light-blue);
  border-radius: 50%;
  color: var(--navy);
}
.greeting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 24px 16px 0;
  max-width: 1280px;
  margin: auto;
}
.greeting-row > span {
  font-size: var(--small-font-size);
  color: #69788a;
  font-weight: 550;
}
.location-button {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 42px;
  padding: 10px 13px;
  border: 1px solid #dce5ed;
  background: white;
  border-radius: 999px;
  font-size: var(--small-font-size);
  font-weight: 600;
  color: var(--navy);
  max-width: 66%;
}
.location-button > span:first-of-type {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.location-chevron {
  font-size: 15px;
  margin-left: 2px;
}
.mobile-bottom-nav {
  position: fixed;
  z-index: 50;
  bottom: 0;
  left: 0;
  right: 0;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  height: calc(77px + env(safe-area-inset-bottom, 0px));
  padding: 7px 9px calc(6px + env(safe-area-inset-bottom, 0px));
  background: #fff;
  border-top: 1px solid #e5edf3;
  box-shadow: 0 -7px 30px #082b4c0a;
}
.mobile-bottom-nav > a {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-size: var(--small-font-size);
  font-weight: 550;
  color: #617180;
  position: relative;
  min-width: 0;
  transition: color 0.2s;
}
.mobile-bottom-nav > a svg {
  stroke-width: 1.8;
}
.mobile-bottom-nav > a.active {
  color: var(--blue);
}
.mobile-bottom-nav > a.active:after {
  content: "";
  position: absolute;
  bottom: 0;
  width: 16px;
  height: 3px;
  background: var(--blue);
  border-radius: 5px;
}
.mobile-bottom-nav .bottom-call {
  justify-content: end;
}
.bottom-call > span {
  position: absolute;
  width: 61px;
  height: 61px;
  background: var(--accent-orange);
  color: white;
  border: 5px solid #fff;
  border-radius: 50%;
  top: -25px;
  display: grid;
  place-items: center;
  box-shadow: 0 7px 21px #f96a133d;
}
.bottom-call small {
  font-size: var(--small-font-size);
  color: var(--navy);
  padding-bottom: 6px;
}
.bottom-call svg,
.call-icon svg {
  animation: phone-ring 5s 1s infinite;
}
@keyframes phone-ring {
  0%,
  84%,
  100% {
    transform: rotate(0);
  }
  87%,
  93% {
    transform: rotate(13deg);
  }
  90%,
  96% {
    transform: rotate(-13deg);
  }
}
#site-shell {
  padding-bottom: calc(77px + env(safe-area-inset-bottom, 0px));
}
.hero {
  margin: 22px 16px 0;
  display: grid;
  gap: 16px;
  max-width: 1280px;
}
.hero-copy {
  position: relative;
  isolation: isolate;
  background: linear-gradient(125deg, #082b4c, #0a3c67);
  border-radius: 25px;
  padding: 31px 23px 26px;
  overflow: visible;
}
.hero-watermark {
  position: absolute;
  width: 240px;
  height: 240px;
  right: -10px;
  top: 6px;
  opacity: 0.055;
  color: white;
  pointer-events: none;
  z-index: -1;
}
.hero .eyebrow {
  color: #83c5e9;
  font-size: var(--small-font-size);
  letter-spacing: 1.5px;
}
.hero h1 {
  color: white;
  font-size: var(--hero-font-size);
  line-height: 1.075;
  letter-spacing: -1.5px;
  margin: 0 0 20px;
}
.hero h1 span {
  color: #91d4fa;
}
.hero-description {
  color: #c3d9e9;
  font-size: var(--supporting-font-size);
  line-height: 1.7;
  margin-bottom: 24px;
  max-width: 500px;
}
.hero-search {
  position: relative;
  z-index: 10;
  margin-bottom: 16px;
}
.hero-search-field {
  display: flex;
  gap: 10px;
  align-items: center;
  min-height: 54px;
  border-radius: 999px;
  padding: 0 15px;
  border: 1px solid #ffffff4a;
  background: #ffffff10;
  color: #c8e0ef;
}
.hero-search input {
  color: white;
  background: transparent;
  border: 0;
  outline: 0 !important;
  box-shadow: none;
  border-radius: 0;
  min-width: 0;
  width: 100%;
  font-size: clamp(10px, 2.8vw, 14px);
  padding: 16px 0;
  margin: 0;
  font-weight: 450;
}
.hero-search input::placeholder {
  color: #d0e0eb;
  opacity: 1;
}
.hero-search button {
  border: 0;
  background: none;
  color: inherit;
  padding: 8px;
  display: flex;
}
.hero-search-field > svg {
  width: 18px;
}
.service-suggestions {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: #fff;
  color: var(--navy);
  padding: 10px;
  border-radius: 16px;
  box-shadow: 0 20px 60px #00192f45;
  border: 1px solid var(--border);
  max-height: 325px;
  overflow-y: auto;
}
.service-suggestions .result-label {
  padding: 7px 9px;
}
.service-suggestions button {
  color: var(--navy);
  padding: 12px 10px;
  min-height: 43px;
  border-radius: 8px;
  justify-content: space-between;
  width: 100%;
  font-size: var(--small-font-size);
  text-align: left;
  gap: 10px;
}
.service-suggestions button[aria-selected="true"],
.service-suggestions button:hover {
  background: var(--light-blue);
  color: var(--blue);
}
.service-suggestions p {
  padding: 10px;
  font-size: var(--small-font-size);
}
.call {
  padding: 8px 15px 8px 9px;
  justify-content: flex-start;
  gap: 12px;
  box-shadow: 0 7px 20px #f96a1320;
}
.call-icon {
  width: 35px;
  height: 35px;
  border-radius: 50%;
  background: var(--navy);
  color: white;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.call-copy {
  display: block;
  text-align: left;
  min-width: 0;
  flex: 1;
}
.call-copy strong {
  display: block;
  font-size: 15px;
  font-weight: 750;
  line-height: 1.3;
  letter-spacing: -0.25px;
}
.call-copy small {
  display: block;
  color: #fff0e6;
  font-size: var(--small-font-size);
  line-height: 1.5;
  margin-top: 2px;
}
.call.prominent {
  width: 100%;
  min-height: 65px;
}
.call.prominent .call-icon {
  width: 43px;
  height: 43px;
}
.call.prominent .call-copy strong {
  font-size: clamp(14px, 4.2vw, 20px);
}
.call.compact {
  min-height: 42px;
  padding: 6px 13px 6px 6px;
  gap: 8px;
  box-shadow: none;
}
.call.compact .call-icon {
  width: 27px;
  height: 27px;
}
.call.compact .call-copy strong {
  font-size: var(--small-font-size);
}
.hero-plan {
  background: none;
  border: 0;
  color: #d4e6f0;
  display: flex;
  gap: 8px;
  align-items: center;
  justify-content: center;
  width: 100%;
  font-size: var(--small-font-size);
  margin-top: 20px;
  padding: 5px 0;
}
.hero-plan svg {
  width: 14px;
}
.hero-assurance {
  display: none;
}
.hero-visual {
  position: relative;
  border-radius: 23px;
  overflow: hidden;
  min-height: 265px;
  background: #d8e8f3;
}
.hero-visual > img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  object-position: center 43%;
}
.photo-label {
  position: absolute;
  bottom: 22px;
  left: 17px;
  right: 17px;
  background: #fff;
  padding: 13px 15px;
  display: flex;
  align-items: center;
  gap: 10px;
  border-radius: 12px;
  box-shadow: 0 8px 30px #082b4c24;
}
.photo-label > span {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--light-blue);
  display: grid;
  place-items: center;
  color: var(--blue);
}
.photo-label strong {
  display: block;
  font-size: var(--small-font-size);
  color: var(--navy);
}
.photo-label small {
  font-size: var(--small-font-size);
  display: block;
  margin-top: 2px;
}
.photo-caption {
  display: none;
}
.trust-strip {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin: 25px 20px 0;
  padding: 0 0 26px;
  border-bottom: 1px solid var(--border);
}
.trust-strip > div {
  display: flex;
  align-items: center;
  gap: 10px;
}
.trust-strip > div:last-child {
  display: none;
}
.trust-strip > div > span {
  width: 35px;
  height: 35px;
  background: var(--light-blue);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--navy);
}
.trust-strip svg {
  width: 18px;
}
.trust-strip p {
  margin: 0;
  line-height: 1.5;
}
.trust-strip strong {
  font-size: var(--small-font-size);
  display: block;
  color: var(--navy);
}
.trust-strip small {
  font-size: var(--small-font-size);
  display: block;
  margin-top: 3px;
}
.section {
  max-width: 1280px;
  margin: 0 auto;
  padding: 46px 20px;
}
.section-title {
  margin-bottom: 25px;
}
.section-title h2 {
  margin-bottom: 10px;
}
.section-title p {
  font-size: var(--small-font-size);
  margin-bottom: 0;
}
.section-title .text-link {
  margin-top: 17px;
}
.service-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 20px;
}
.service-card {
  background: white;
  border: 1px solid var(--border);
  border-radius: 15px;
  overflow: hidden;
  box-shadow: 0 4px 18px #082b4c03;
  min-width: 0;
  transition: box-shadow 0.2s;
}
.service-card:hover {
  box-shadow: 0 12px 28px #082b4c0e;
}
.service-image {
  display: block;
  position: relative;
  height: 190px;
  background: var(--light-blue);
}
.service-image > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s;
}
.service-image {
  overflow: visible;
}
.service-image > img {
  border-radius: 14px 14px 0 0;
}
.service-card:hover .service-image > img {
  filter: brightness(1.04);
}
.category {
  position: absolute;
  left: 12px;
  top: 12px;
  padding: 5px 8px;
  background: #fffffff2;
  font-size: var(--small-font-size);
  font-weight: 600;
  color: var(--navy);
  border-radius: 5px;
}
.service-icon {
  position: absolute;
  bottom: -20px;
  left: 20px;
  width: 43px;
  height: 43px;
  border-radius: 50%;
  background: white;
  border: 3px solid #fff;
  display: grid;
  place-items: center;
  color: var(--navy);
  box-shadow: 0 2px 12px #082b4c10;
}
.service-body {
  padding: 31px 20px 18px;
  position: relative;
}
.service-body h3 {
  font-size: 21px;
  margin-bottom: 10px;
}
.service-body p {
  font-size: var(--small-font-size);
  line-height: 1.75;
  margin-bottom: 18px;
}
.learn-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: var(--small-font-size);
  font-weight: 650;
  color: var(--navy);
}
.card-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  justify-content: space-between;
  margin-top: 15px;
  padding-top: 15px;
  border-top: 1px solid #e7edf3;
}
.service-card .card-actions > * {
  width: 100%;
}
.card-plan {
  border-radius: 9px;
  background: var(--light-blue);
  color: var(--navy);
  justify-content: space-between;
  min-height: 42px;
  font-size: var(--small-font-size);
  box-shadow: none;
}
.card-plan:hover {
  background: #dbeefa;
  box-shadow: none;
}
.service-card .call {
  border-radius: 8px;
  justify-content: center;
}
.image-placeholder {
  height: 100%;
  min-height: 140px;
  background: linear-gradient(130deg, #d7e9f4, #abcbdc);
  color: #497b9a;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 12px;
}
.image-placeholder span {
  font-size: var(--small-font-size);
}
.why-section {
  background: var(--light-blue);
}
.why-intro {
  background: var(--navy);
  padding: 36px 24px;
  color: white;
}
.why-intro h2 {
  color: white;
}
.why-intro .eyebrow {
  color: #6cbeee;
}
.why-intro p {
  color: #bed1e0;
  font-size: var(--small-font-size);
}
.benefit-grid {
  display: grid;
  padding: 32px 23px;
  gap: 25px;
}
.benefit-grid > div {
  display: flex;
  align-items: start;
  gap: 16px;
}
.feature-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  background: #dcecf7;
  border-radius: 50%;
  color: var(--navy);
  flex-shrink: 0;
}
.benefit-grid h3 {
  font-size: 16px;
  margin: 4px 0 7px;
}
.benefit-grid p {
  font-size: var(--small-font-size);
  margin: 0;
}
.how .section-title {
  text-align: center;
}
.steps-grid {
  display: grid;
  gap: 18px;
}
.process-card {
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 16px;
  padding: 28px 24px;
  position: relative;
}
.step-number {
  position: absolute;
  right: 24px;
  top: 24px;
  color: #c5d9e7;
  font-size: 27px;
  font-weight: 700;
}
.process-icon {
  display: grid;
  place-items: center;
  height: 62px;
  width: 62px;
  background: var(--light-blue);
  border-radius: 50%;
  color: var(--navy);
  margin-bottom: 24px;
}
.process-card h3 {
  font-size: 20px;
}
.process-card p {
  font-size: var(--small-font-size);
  margin: 0;
}
.emergency {
  background: linear-gradient(110deg, #082b4c, #0c3d62);
  padding: 40px 24px;
  margin: 0 0 5px;
  position: relative;
  overflow: hidden;
}
.emergency:after {
  content: "";
  position: absolute;
  right: -40px;
  top: -60px;
  width: 300px;
  height: 300px;
  border: 40px solid #ffffff03;
  border-radius: 50%;
  pointer-events: none;
}
.emergency .eyebrow {
  color: #71bbe4;
}
.emergency h2 {
  color: #fff;
  font-size: 30px;
}
.emergency p {
  color: #bcd3e3;
  font-size: var(--small-font-size);
  max-width: 520px;
}
.emergency > div:last-child {
  position: relative;
  z-index: 1;
}
.emergency small {
  display: block;
  color: #aec6d7;
  font-size: var(--small-font-size);
  margin-top: 14px;
}
.locations-home {
  display: grid;
  gap: 20px;
}
.location-feature {
  background: var(--light-blue);
  padding: 28px;
  border-radius: 17px;
}
.location-feature h3 {
  font-size: 25px;
  margin-top: 20px;
}
.location-feature p {
  font-size: var(--small-font-size);
}
.location-preview {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 11px;
}
.location-preview > a {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--border);
  background: white;
  border-radius: 10px;
  padding: 17px 12px;
  min-width: 0;
}
.location-preview > a > span {
  font-size: var(--small-font-size);
  font-weight: 700;
  color: var(--blue);
}
.location-preview strong {
  font-size: var(--small-font-size);
  font-weight: 600;
