/* Readability and shared sizing. All editable values live in variables.css. */
body { font-size: var(--body-font-size); }
p, .lead, .hero-description, .detail-hero .lead { font-size: var(--body-font-size); }
small { font-size: var(--small-font-size); }
.button, button.button, input, select, textarea { font-size: var(--button-font-size); }
label { font-size: var(--supporting-font-size); }
h2, .section-title h2, .faq-section h2 { font-size: var(--section-heading-size); }
.hero h1 { font-size: var(--hero-font-size); }
.section { max-width: var(--container-width); padding-top: var(--section-spacing); padding-bottom: var(--section-spacing); }
footer a:not(.brand), .footer-brand p { font-size: var(--small-font-size); }
.eyebrow { font-size: 12px; letter-spacing: .14em; }
.hero-assurance, .hero-plan, .text-link, .faq-item > button { font-size: var(--supporting-font-size); }

/* Existing vector mark + wordmark scale together without stretching an image. */
.brand, .footer-columns .brand {
  width: var(--logo-width); flex: 0 0 var(--logo-width); gap: .4em;
  font-size: calc(var(--logo-width) * .088); letter-spacing: -.04em;
}
.brand > span:last-child { min-width: 0; }
.brand small { font-size: .31em; letter-spacing: .15em; margin-top: .25em; }
.brand .logo { width: 1.6em; height: 1.75em; }
.brand .logo > svg:first-child { width: 1.6em; height: 1.6em; }
.brand .logo > svg:last-child { width: .69em; height: .69em; left: .55em; bottom: .05em; }
header { height: var(--header-height); }
.desktop-nav, .desktop-nav.open { font-size: var(--navbar-font-size); font-weight: 600; line-height: 1.4; letter-spacing: 0; }
.desktop-nav > a, .services-nav > a { font-size: var(--navbar-font-size); }
.desktop-nav a:hover { color: var(--blue); }
.mega-links a { font-size: var(--supporting-font-size); min-height: 44px; }
.header-actions { flex-shrink: 0; }
.header-actions > .location-button { font-size: 14px; }
.header-actions > .call .call-copy strong { font-size: var(--button-font-size); }
.desktop-nav.open { top: var(--header-height); }

/* SERVICE GRID: two columns through tablet, exactly four from 1024px.
   List view uses .services-list and remains independent. */
.service-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--card-spacing); }
.service-card:not(.list-card) { display: flex; flex-direction: column; }
.service-card:not(.list-card) .service-image { height: auto; aspect-ratio: 1.4; }
.service-card:not(.list-card) .service-body { padding: 26px 12px 12px; flex: 1; display: flex; flex-direction: column; }
.service-body h3 { font-size: var(--card-title-size); line-height: 1.3; letter-spacing: -.025em; }
.service-body p { font-size: var(--card-description-size); line-height: 1.55; margin-bottom: 12px; }
.service-card:not(.list-card) .service-body p { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.service-card .learn-link { font-size: 14px; min-height: 44px; margin-top: auto; }
.service-card .card-actions { margin-top: 6px; padding-top: 10px; }
.service-card .button { padding: 9px 7px; gap: 5px; min-height: 44px; font-size: 14px; }
.service-card .button > svg:last-child { display: none; }
.service-card .call-icon { width: 24px; height: 24px; }
.service-card .call-copy strong { font-size: 14px; }
.service-card .category { top: 8px; left: 8px; right: 8px; width: fit-content; max-width: calc(100% - 16px); font-size: 11px; line-height: 1.4; padding: 4px 5px; }
.list-card .service-body h3 { font-size: var(--card-title-size); }
.list-card .service-body p { font-size: var(--card-description-size); }
.service-icon { left: 12px; }
.hero-plan { white-space: normal; text-align: left; }
.call-copy { min-width: 0; }
.photo-label { max-width: calc(100% - 24px); }
.photo-label small { font-size: 12px; }
@media (max-width: 359px) {
  .service-grid { gap: 8px; }
  .service-card:not(.list-card) .service-body { padding-left: 9px; padding-right: 9px; }
  .service-body h3 { font-size: 15px; }
  .service-body p { font-size: 13px; }
  .service-card .button { font-size: 13px; padding-inline: 5px; }
  .service-card .button > svg { width: 14px; }
}
@media (min-width: 768px) {
  .service-card:not(.list-card) .service-body { padding: 30px 18px 18px; }
  .service-grid.home-services { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 1024px) {
  .service-grid, .service-grid.home-services { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
/* Full navigation only when logo, all seven links, and actions fit comfortably. */
@media (min-width: 1320px) and (max-width: 1439px) {
  header { padding-inline: 30px; gap: 20px; }
  .desktop-nav:not(.open) { display: none; }
  .tablet-menu { display: grid; margin-left: auto; }
  .desktop-nav.open { position: absolute; top: var(--header-height); left: 0; right: 0; flex-wrap: wrap; background: white; padding: 20px 30px; }
}
@media (min-width: 1440px) {
  header { padding-inline: max(24px, calc((100vw - 1440px) / 2)); gap: 20px; }
  .desktop-nav { flex: 1; justify-content: center; gap: clamp(14px, 1.2vw, 22px); }
  .header-actions { gap: 10px; }
  .header-actions > .location-button { max-width: 190px; }
}

/* Supporting prose remains comfortably readable without enlarging metadata. */
.benefit-grid p, .process-card p, .emergency p, .location-feature p,
.planning-banner p, .faq-item p, .detail-content p, .estimator p,
.before-call p, .service-call-process p, .project-card details p,
.modal > p, .ticket p, .location-modal > p { font-size: var(--supporting-font-size); }
.mobile-bottom-nav small { font-size: 12px; }

.mobile-bottom-nav > a:not(.bottom-call) > span { font-size: 12px; }
